<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function kimpu_register_header_settings( $c ) {
    $c->add_section( 'kimpu_header', array( 'title' => __( 'Header Builder', 'kimpu-multipurpose' ), 'priority' => 30 ) );
    $selects = array( 'kimpu_header_layout' => array( 'default', array( 'default' => __( 'Default', 'kimpu-multipurpose' ), 'centered' => __( 'Centered', 'kimpu-multipurpose' ), 'minimal' => __( 'Minimal', 'kimpu-multipurpose' ) ), __( 'Header Layout', 'kimpu-multipurpose' ) ), 'kimpu_mobile_menu_style' => array( 'drawer', array( 'drawer' => __( 'Slide-in Drawer', 'kimpu-multipurpose' ), 'dropdown' => __( 'Dropdown', 'kimpu-multipurpose' ) ), __( 'Mobile Menu Style', 'kimpu-multipurpose' ) ) );
    foreach ( $selects as $id => $data ) { $c->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => function( $value ) use ( $data ) { return array_key_exists( $value, $data[1] ) ? $value : $data[0]; } ) ); $c->add_control( $id, array( 'label' => $data[2], 'section' => 'kimpu_header', 'type' => 'select', 'choices' => $data[1] ) ); }
    $bools = array( 'kimpu_sticky_header' => __( 'Enable Sticky Header', 'kimpu-multipurpose' ), 'kimpu_header_border' => __( 'Show Header Border', 'kimpu-multipurpose' ), 'kimpu_header_shadow' => __( 'Show Header Shadow', 'kimpu-multipurpose' ), 'kimpu_header_cta_enabled' => __( 'Enable Header CTA', 'kimpu-multipurpose' ), 'kimpu_search_enabled' => __( 'Enable Search Button', 'kimpu-multipurpose' ) );
    foreach ( $bools as $id => $label ) { $c->add_setting( $id, array( 'default' => false, 'sanitize_callback' => 'rest_sanitize_boolean' ) ); $c->add_control( $id, array( 'label' => $label, 'section' => 'kimpu_header', 'type' => 'checkbox' ) ); }
    $c->add_setting( 'kimpu_header_background', array( 'default' => '#ffffff', 'sanitize_callback' => 'sanitize_hex_color' ) ); $c->add_control( new WP_Customize_Color_Control( $c, 'kimpu_header_background', array( 'label' => __( 'Header Background', 'kimpu-multipurpose' ), 'section' => 'kimpu_header' ) ) );
    $c->add_setting( 'kimpu_header_text_color', array( 'default' => '#17283b', 'sanitize_callback' => 'sanitize_hex_color' ) ); $c->add_control( new WP_Customize_Color_Control( $c, 'kimpu_header_text_color', array( 'label' => __( 'Header Text Color', 'kimpu-multipurpose' ), 'section' => 'kimpu_header' ) ) );
    $fields = array( 'kimpu_header_height' => array( 84, __( 'Header Height (px)', 'kimpu-multipurpose' ), 56, 160 ), 'kimpu_header_cta_label' => array( __( 'Get started', 'kimpu-multipurpose' ), __( 'CTA Label', 'kimpu-multipurpose' ) ), 'kimpu_header_cta_url' => array( home_url( '/contact/' ), __( 'CTA URL', 'kimpu-multipurpose' ) ) );
    foreach ( $fields as $id => $data ) { $is_url = false !== strpos( $id, '_url' ); $c->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => $is_url ? 'esc_url_raw' : ( is_int( $data[0] ) ? 'absint' : 'sanitize_text_field' ) ) ); $control = array( 'label' => $data[1], 'section' => 'kimpu_header', 'type' => $is_url ? 'url' : ( is_int( $data[0] ) ? 'number' : 'text' ) ); if ( is_int( $data[0] ) ) { $control['input_attrs'] = array( 'min' => $data[2], 'max' => $data[3] ); } $c->add_control( $id, $control ); }
}
